-- PostgreSQL baseline corresponding to SQLite migrations 001–041.
-- SQLite history remains immutable for the offline importer.

CREATE FUNCTION ascii_fold(text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$ SELECT translate($1, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') $$;

CREATE TABLE "account_allocations" (
