  "last_active_at" text COLLATE "C",
  "created_at" text COLLATE "C",
  "updated_at" text COLLATE "C",
  "deleted_at" text COLLATE "C",
  "vm_create_quota" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);

CREATE INDEX "idx_users_deleted_at" ON "users" ("deleted_at");
CREATE INDEX "idx_users_status" ON "users" ("status");
CREATE UNIQUE INDEX "idx_users_email_active" ON "users" ("email") WHERE  deleted_at IS NULL;
CREATE UNIQUE INDEX "idx_users_username_active" ON "users" (ascii_fold("username")) WHERE  deleted_at IS NULL;

CREATE TABLE "vm_pool_members" (
  "pool_id" text COLLATE "C" NOT NULL,
  "vm_id" text COLLATE "C" NOT NULL,
  "created_at" text COLLATE "C" NOT NULL,
  PRIMARY KEY ("pool_id", "vm_id")
);

CREATE UNIQUE INDEX "idx_vm_pool_members_vm" ON "vm_pool_members" ("vm_id");

CREATE TABLE "vm_pools" (
  "id" text COLLATE "C",
  "name" text COLLATE "C" NOT NULL,
  "enabled" bigint NOT NULL DEFAULT 1,
  "created_at" text COLLATE "C" NOT NULL,
  "updated_at" text COLLATE "C" NOT NULL,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "idx_vm_pools_name" ON "vm_pools" (ascii_fold("name"));

CREATE TABLE "vms" (
  "id" text COLLATE "C",
  "name" text COLLATE "C",
  "status" text COLLATE "C",
  "schedulable" bigint DEFAULT 1,
  "email" text COLLATE "C",
  "account_uuid" text COLLATE "C",
  "org_uuid" text COLLATE "C",
  "access_token" text COLLATE "C",
  "refresh_token" text COLLATE "C",
  "session_key" text COLLATE "C",
  "oauth_expires_at" text COLLATE "C",
  "oauth_source" text COLLATE "C",
  "proxy_id" text COLLATE "C",
  "claude_code_version" text COLLATE "C",
  "timezone" text COLLATE "C",
  "locale" text COLLATE "C",
  "vm_json" text COLLATE "C" NOT NULL,
  "encrypted" bigint DEFAULT 0,
  "file_mtime_ms" bigint,
  "synced_at" text COLLATE "C",
  "created_at" text COLLATE "C",
  "updated_at" text COLLATE "C",
  "owner_user_id" text COLLATE "C",
  "origin" text COLLATE "C" NOT NULL DEFAULT 'platform',
  PRIMARY KEY ("id")
);

CREATE INDEX "idx_vms_origin" ON "vms" ("origin");
CREATE INDEX "idx_vms_owner" ON "vms" ("owner_user_id");
CREATE INDEX "idx_vms_account" ON "vms" ("account_uuid");

CREATE TABLE thinking_signature_owners (key text COLLATE "C" PRIMARY KEY, account_id text COLLATE "C" NOT NULL, created_at bigint NOT NULL);
CREATE INDEX idx_thinking_owner_created ON thinking_signature_owners(created_at);

